export function evaluate({inputs,time}){
const u=inputs.launchSpeed,g=inputs.gravity,m=inputs.mass;
const T=2*u/g,ta=u/g;
const t=Math.min(Math.max(time,0),T);
const v=u-g*t,h=Math.max(0,u*t-g*t*t/2),ah=u*u/(2*g);
const eps=1e-6;
let st='Rising';
if(time<=0)st='Ready to toss';else if(Math.abs(t-ta)<0.005)st='At the top';else if(t>=T-eps)st='Back at launch height';else if(t>ta)st='Falling';
const o=[];
o.push(...sdk.panel({id:'lane.motion',x:10,y:34,w:310,h:370,title:'The motion',state:st}));
o.push(...sdk.panel({id:'lane.graph',x:330,y:34,w:300,h:370,title:'Velocity over time',state:'v = u - g t'}));
o.push(sdk.axis('axis.h',{x:70,y:380,length:320,orientation:'y',min:0,max:2.2,ticks:[0,1,2],label:'Height',unit:'m'}));
const py=380-h/2.2*320;
o.push(sdk.circle('ball.toss',110,py,26,{}));
o.push(...sdk.vector('vec.v',{x:110,y:py},{value:v,direction:'up'},{scale:14,label:'v',role:'observed'}));
o.push(...sdk.vector('vec.a',{x:140,y:py},{value:-g,direction:'up'},{scale:6,label:'a',role:'warning'}));
o.push(sdk.callout(190,150,['v = '+sdk.format(v,2)+' m/s','a = '+sdk.format(-g,2)+' m/s^2','Fg = '+sdk.format(m*g,2)+' N'],{id:'callout.toss'}));
const pts=[];for(let i=0;i<=12;i++){const tt=T*i/12;pts.push({x:tt*1.8/T*1,y:u-g*tt});}
const cur=[];const n=Math.max(1,Math.round(12*t/T));for(let i=0;i<=n;i++){const tt=t*i/n;cur.push({x:tt,y:u-g*tt});}
if(cur.length<2)cur.push({x:t+0.001,y:u-g*(t+0.001)});
const full=[];for(let i=0;i<=12;i++){const tt=1.8*i/12;full.push({x:tt,y:sdk.clamp(u-g*tt,-5.5,5.5)});}
o.push(sdk.plot('plot.vt',{x:360,y:70,w:260,h:290,axes:{x:{label:'t',min:0,max:1.8,unit:'s'},y:{label:'v',min:-5.5,max:5.5,unit:'m/s'}},series:[{label:'v = u - g t',kind:'line',points:full},{label:'so far',kind:'line',points:cur.map(p=>({x:Math.min(p.x,1.8),y:sdk.clamp(p.y,-5.5,5.5)}))}]}));
o.push(sdk.text('plot.vt.note',490,392,'slope a = -g',{align:'middle'}));
return {frame:{width:640,height:420,objects:o,readouts:[{id:'velocity',value:v},{id:'acceleration',value:-g},{id:'force',value:m*g},{id:'motionState',value:st}]},quantities:{launchSpeed:u,gravity:g,mass:m,apexTime:ta,apexHeight:ah,height:h,velocity:v,acceleration:-g,force:m*g}};
}
